`WorkArchive` stores `WorkItem` values in insertion order. IDs must be positive safe integers, titles must contain a non-whitespace character, and `done` must be boolean; invalid values throw `TypeError` or `RangeError`. Valid titles remain exact.

`add` returns `false` for a duplicate ID and otherwise stores a copy. `find` returns a fresh copy or `null`. `replace` returns `null` for a missing ID; otherwise it replaces the item without changing its position and returns a copy of the previous item. `delete` returns and removes only the matching item, or returns `null` if absent. `list` returns fresh objects in insertion order. No input or returned object may alias stored state, and failed operations must not mutate the archive.

Known-bad source:
```ts
export interface WorkItem {
  id: number;
  title: string;
  done: boolean;
}

export class WorkArchive {
  private readonly items: WorkItem[] = [];

  add(item: WorkItem): boolean {
    this.validateItem(item);
    if (this.items.some((current) => current.id === item.id)) {
      return false;
    }
    this.items.push({ ...item });
    return true;
  }

  find(id: number): WorkItem | null {
    this.validateId(id);
    const item = this.items.find((current) => current.id === id);
    return item === undefined ? null : { ...item };
  }

  replace(item: WorkItem): WorkItem | null {
    this.validateItem(item);
    const index = this.items.findIndex((current) => current.id === item.id);
    if (index < 0) {
      return null;
    }
    const previous = this.items[index];
    this.items[index] = { ...item };
    return { ...previous };
  }

  delete(id: number): WorkItem | null {
    this.validateId(id);
    const index = this.items.findIndex((current) => current.id === id);
    if (index < 0) {
      return null;
    }
    const removed = this.items.splice(index);
    return { ...removed[0] };
  }

  list(): WorkItem[] {
    return this.items.map((item) => ({ ...item }));
  }

  private validateItem(item: WorkItem): void {
    if (item === null || typeof item !== "object") {
      throw new TypeError("item must be an object");
    }
    this.validateId(item.id);
    if (typeof item.title !== "string" || item.title.trim().length === 0) {
      throw new TypeError("title must contain non-whitespace characters");
    }
    if (typeof item.done !== "boolean") {
      throw new TypeError("done must be boolean");
    }
  }

  private validateId(id: number): void {
    if (!Number.isSafeInteger(id) || id <= 0) {
      throw new RangeError("id must be a positive safe integer");
    }
  }
}
```

