import { WorkArchive, WorkItem } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function itemEqual(actual: WorkItem | null, expected: WorkItem | null, message: string): void {
  if (expected === null) { equal(actual, null, message); return; }
  assert(actual !== null, `${message}: missing item`);
  equal(actual.id, expected.id, `${message}: id`);
  equal(actual.title, expected.title, `${message}: title`);
  equal(actual.done, expected.done, `${message}: done`);
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof TypeError, message); return; }
  throw new Error(`${message}: did not throw`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof RangeError, message); return; }
  throw new Error(`${message}: did not throw`);
}

const archive = new WorkArchive();
const emptyA = archive.list();
const emptyB = archive.list();
equal(emptyA.length, 0, 'empty archive');
assert(emptyA !== emptyB, 'empty lists are fresh');

const source: WorkItem = { id: 1, title: ' first ', done: false };
equal(archive.add(source), true, 'add item');
source.title = 'mutated';
source.done = true;
itemEqual(archive.find(1), { id: 1, title: ' first ', done: false }, 'input copied');
equal(archive.add({ id: 1, title: 'duplicate', done: true }), false, 'duplicate returns false');
itemEqual(archive.find(1), { id: 1, title: ' first ', done: false }, 'duplicate is stable');
equal(archive.add({ id: 2, title: 'second', done: true }), true, 'add second');
equal(archive.add({ id: 3, title: 'third', done: false }), true, 'add third');

const found = archive.find(1);
assert(found !== null, 'found copy');
found.title = 'changed';
itemEqual(archive.find(1), { id: 1, title: ' first ', done: false }, 'find result isolated');
assert(archive.find(1) !== archive.find(1), 'find results fresh');
itemEqual(archive.find(99), null, 'missing find');

const replacement: WorkItem = { id: 2, title: ' updated ', done: false };
const previous = archive.replace(replacement);
itemEqual(previous, { id: 2, title: 'second', done: true }, 'replace returns previous');
replacement.title = 'later';
assert(previous !== null, 'previous exists');
previous.title = 'mutated previous';
itemEqual(archive.find(2), { id: 2, title: ' updated ', done: false }, 'replace aliases isolated');
itemEqual(archive.replace({ id: 99, title: 'missing', done: false }), null, 'missing replace');
const ordered = archive.list();
equal(ordered.map((item) => item.id).join(','), '1,2,3', 'replace retains order');
ordered[0].title = 'list mutation';
itemEqual(archive.find(1), { id: 1, title: ' first ', done: false }, 'list objects are copied');

itemEqual(archive.delete(2), { id: 2, title: ' updated ', done: false }, 'delete returns matching item');
itemEqual(archive.delete(2), null, 'delete missing');
equal(archive.list().map((item) => item.id).join(','), '1,3', 'delete removes only match');

for (const id of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1, Infinity, NaN]) {
  throwsRange(() => archive.find(id), 'invalid find ID');
  throwsRange(() => archive.delete(id), 'invalid delete ID');
  throwsRange(() => archive.add({ id, title: 'valid', done: false }), 'invalid item ID');
}
throwsType(() => archive.add(null as unknown as WorkItem), 'null item');
throwsType(() => archive.add({ id: 4, title: '   ', done: false }), 'blank title');
throwsType(() => archive.add({ id: 4, title: 'valid', done: 1 as unknown as boolean }), 'non-boolean done');
equal(archive.list().map((item) => item.id).join(','), '1,3', 'failed operations do not mutate');

